style.css:
@-moz-document domain("youtube.com") {
/* GLOW RIOT - HOMEPAGE RAINBOW TITLES */

@keyframes glow-riot-rainbow {
  0% {
    color: #ff0000;
    -webkit-text-fill-color: #ff0000;
    text-shadow: 0 0 8px #ff0000;
  }
  12.5% {
    color: #ff8000;
    -webkit-text-fill-color: #ff8000;
    text-shadow: 0 0 8px #ff8000;
  }
  25% {
    color: #ffff00;
    -webkit-text-fill-color: #ffff00;
    text-shadow: 0 0 8px #ffff00;
  }
  37.5% {
    color: #39ff14;
    -webkit-text-fill-color: #39ff14;
    text-shadow: 0 0 8px #39ff14;
  }
  50% {
    color: #00ffcc;
    -webkit-text-fill-color: #00ffcc;
    text-shadow: 0 0 8px #00ffcc;
  }
  62.5% {
    color: #008cff;
    -webkit-text-fill-color: #008cff;
    text-shadow: 0 0 8px #008cff;
  }
  75% {
    color: #a020f0;
    -webkit-text-fill-color: #a020f0;
    text-shadow: 0 0 8px #a020f0;
  }
  87.5% {
    color: #ff1493;
    -webkit-text-fill-color: #ff1493;
    text-shadow: 0 0 8px #ff1493;
  }
}

/* HOMEPAGE VIDEO TITLES */

yt-lockup-view-model .yt-lockup-metadata-view-model__title,
yt-lockup-view-model .ytLockupMetadataViewModelTitle,
ytd-rich-grid-media #video-title,
ytd-rich-grid-media #video-title-link {

  font-family: "Comic Sans MS", cursive !important;
  font-weight: 900 !important;
  animation: glow-riot-rainbow 8s steps(1, end) infinite !important;
}

/* MAKE INNER TITLE TEXT ANIMATE TOO */

yt-lockup-view-model .yt-lockup-metadata-view-model__title *,
yt-lockup-view-model .ytLockupMetadataViewModelTitle * {

  animation: glow-riot-rainbow 8s steps(1, end) infinite !important;
}
}
